"""`!unsloth install-kernels` replaces the hand-written xformers / causal_conv1d wheel picks.

The command runs the `unsloth` CLI, so it only works after the cell installed unsloth. ROCm
has no prebuilt wheels, so AMD cells keep their own lines and never call it.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
KERNELS = re.compile(r"^\s*!unsloth install-kernels\b", re.MULTILINE)
INSTALLS_UNSLOTH = re.compile(r'^\s*!(?:uv )?pip install\b.*(?:\s|")unsloth(?:\s|"|>|=|\[|$)', re.MULTILINE)
RETIRED = (
    "xformers = 'xformers=='",
    "xformers-0.0.35-py39-none-manylinux_2_28_x86_64.whl",
    "{xformers}",
    "causal-conv1d/releases/download/v1.7.0",
)


def _code_cells(path):
    nb = json.loads(path.read_text(encoding="utf-8"))
    for cell in nb["cells"]:
        if cell.get("cell_type") == "code":
            src = cell["source"]
            yield "".join(src) if isinstance(src, list) else src


def _notebooks():
    return sorted((REPO_ROOT / "nb").glob("*.ipynb"))


def test_retired_wheel_picks_are_gone():
    offenders = [
        (path.name, text)
        for path in _notebooks()
        for cell in _code_cells(path)
        for text in RETIRED
        if text in cell
    ]
    assert offenders == []


def test_kernel_line_follows_the_unsloth_install():
    seen = 0
    for path in _notebooks():
        if path.name.startswith("AMD-"):
            continue
        earlier = ""
        for cell in _code_cells(path):
            for match in KERNELS.finditer(cell):
                seen += 1
                # Join `\`-continued pip lines, which name unsloth on a later physical line.
                before = (earlier + cell[: match.start()]).replace("\\\n", " ")
                assert INSTALLS_UNSLOTH.search(before), (path.name, cell)
            earlier += cell + "\n"
    assert seen > 100


def test_ssm_notebooks_no_longer_build_kernels_from_source():
    offenders = [
        path.name
        for path in _notebooks()
        if not path.name.startswith("AMD-")
        for cell in _code_cells(path)
        if re.search(r"--no-build-isolation[^\n]*(mamba|causal)", cell)
    ]
    assert offenders == []


def test_amd_cells_never_call_it():
    amd = [path for path in _notebooks() if path.name.startswith("AMD-")]
    assert amd
    assert [p.name for p in amd for cell in _code_cells(p) if KERNELS.search(cell)] == []

"""Shared fixtures for the security regression suite.

The scanner scripts under audit are designed to be offline-safe. Pin
that invariant by autouse-installing a session-scoped network blocker
that refuses any non-loopback `socket.connect()` from inside the test
process. If a future test (or a scanner regression) accidentally tries
to reach the public internet, pytest fails loudly instead of leaking
the request.
"""

from __future__ import annotations

import socket
import sys
from pathlib import Path

import pytest


# Make `scripts/` importable as a package so tests can grab the scanner
# constants directly. The repo root sits two levels above this file.
REPO_ROOT = Path(__file__).resolve().parents[2]
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))


_LOOPBACK_PREFIXES = ("127.", "::1", "localhost")


def _is_loopback(host: str | bytes) -> bool:
    if isinstance(host, bytes):
        try:
            host = host.decode("utf-8")
        except UnicodeDecodeError:
            return False
    if not host:
        return False
    host = host.strip()
    if host in {"::1", "localhost", "0.0.0.0"}:
        return True
    return host.startswith("127.")


class _BlockedSocket(socket.socket):
    """Socket subclass that refuses any non-loopback connect()."""

    def connect(self, address):  # type: ignore[override]
        host = None
        if isinstance(address, tuple) and address:
            host = address[0]
        if not _is_loopback(host or ""):
            raise RuntimeError(
                f"network access blocked by tests/security/conftest.py "
                f"(attempted connect to {address!r}); the scanner suite "
                "must run fully offline"
            )
        return super().connect(address)

    def connect_ex(self, address):  # type: ignore[override]
        host = None
        if isinstance(address, tuple) and address:
            host = address[0]
        if not _is_loopback(host or ""):
            raise RuntimeError(
                f"network access blocked by tests/security/conftest.py "
                f"(attempted connect_ex to {address!r})"
            )
        return super().connect_ex(address)


@pytest.fixture(scope = "session", autouse = True)
def network_blocker():
    """Session-scoped fixture; replaces `socket.socket` with a blocker.

    Yields nothing; the swap is the side effect. Restored at teardown
    so other test sessions (run interleaved) see a clean module.
    """
    original = socket.socket
    socket.socket = _BlockedSocket  # type: ignore[assignment]
    try:
        yield
    finally:
        socket.socket = original  # type: ignore[assignment]


@pytest.fixture(scope = "session")
def repo_root() -> Path:
    return REPO_ROOT


@pytest.fixture(scope = "session")
def fixtures_dir() -> Path:
    return Path(__file__).resolve().parent / "fixtures"
